[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Global Aid Alliance — Together We Respond</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --brand-red: #C41E3A;
      --brand-red-dark: #A01830;
      --brand-navy: #1B3A5C;
      --brand-navy-light: #2A4F7A;
      --white: #FFFFFF;
      --gray-50: #F8F9FA;
      --gray-100: #E9ECEF;
      --gray-200: #DEE2E6;
      --gray-300: #CED4DA;
      --gray-400: #ADB5BD;
      --gray-500: #6C757D;
      --gray-600: #495057;
      --gray-700: #343A40;
      --gray-800: #212529;
      --gray-900: #1A1A2E;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -2px rgba(0,0,0,0.05);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
      --radius-sm: 0.25rem;
      --radius-md: 0.5rem;
      --radius-lg: 0.75rem;
      --radius-xl: 1rem;
      --transition-fast: 150ms ease;
      --transition-base: 250ms ease;
      --transition-slow: 350ms ease;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      font-size: 16px;
      line-height: 1.6;
      color: var(--gray-800);
      background-color: var(--white);
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    img {
      max-width: 100%;
      height: auto;
      display: block;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button {
      font-family: inherit;
      cursor: pointer;
      border: none;
      background: none;
    }

    .container {
      width: 100%;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 1.5rem;
    }

    /* Header */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      background: var(--white);
      box-shadow: var(--shadow-sm);
      z-index: 100;
    }

    .header-top {
      background: var(--gray-900);
      color: var(--white);
      font-size: 0.8125rem;
      padding: 0.5rem 0;
    }

    .header-top-inner {
      display: flex;
      justify-content: flex-end;
      gap: 1.5rem;
    }

    .header-top a {
      color: var(--gray-300);
      transition: color var(--transition-fast);
    }

    .header-top a:hover {
      color: var(--white);
    }

    .header-main {
      padding: 1rem 0;
    }

    .header-main-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      font-weight: 700;
      font-size: 1.25rem;
      color: var(--brand-navy);
    }

    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--brand-red);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-weight: 800;
      font-size: 1.125rem;
    }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 2rem;
    }

    .nav-desktop a {
      font-weight: 500;
      font-size: 0.9375rem;
      color: var(--gray-700);
      transition: color var(--transition-fast);
    }

    .nav-desktop a:hover {
      color: var(--brand-red);
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      padding: 0.75rem 1.5rem;
      font-weight: 600;
      font-size: 0.9375rem;
      border-radius: var(--radius-md);
      transition: all var(--transition-fast);
    }

    .btn-primary {
      background: var(--brand-red);
      color: var(--white);
    }

    .btn-primary:hover {
      background: var(--brand-red-dark);
      transform: translateY(-1px);
      box-shadow: var(--shadow-md);
    }

    .btn-secondary {
      background: var(--white);
      color: var(--brand-navy);
      border: 2px solid var(--brand-navy);
    }

    .btn-secondary:hover {
      background: var(--brand-navy);
      color: var(--white);
    }

    .btn-navy {
      background: var(--brand-navy);
      color: var(--white);
    }

    .btn-navy:hover {
      background: var(--brand-navy-light);
    }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 0.5rem;
    }

    .hamburger span {
      display: block;
      width: 24px;
      height: 2px;
      background: var(--gray-700);
      transition: all var(--transition-fast);
    }

    .hamburger.active span:nth-child(1) {
      transform: rotate(45deg) translate(5px, 5px);
    }

    .hamburger.active span:nth-child(2) {
      opacity: 0;
    }

    .hamburger.active span:nth-child(3) {
      transform: rotate(-45deg) translate(5px, -5px);
    }

    /* Mobile Nav */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 99;
      padding-top: 6rem;
      transform: translateX(100%);
      transition: transform var(--transition-base);
    }

    .mobile-nav.active {
      transform: translateX(0);
    }

    .mobile-nav-inner {
      padding: 2rem 1.5rem;
      display: flex;
      flex-direction: column;
      gap: 1.5rem;
    }

    .mobile-nav a {
      display: block;
      padding: 1rem 0;
      font-size: 1.125rem;
      font-weight: 500;
      color: var(--gray-700);
      border-bottom: 1px solid var(--gray-200);
    }

    .mobile-nav .btn {
      width: 100%;
      margin-top: 1rem;
    }

    .mobile-nav-close {
      position: absolute;
      top: 1rem;
      right: 1.5rem;
      font-size: 2rem;
      color: var(--gray-600);
    }

    /* Hero */
    .hero {
      padding: 8rem 0 5rem;
      background: linear-gradient(135deg, var(--brand-navy) 0%, var(--brand-navy-light) 100%);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><circle cx="50" cy="50" r="40" fill="none" stroke="rgba(255,255,255,0.03)" stroke-width="0.5"/></svg>') repeat;
      background-size: 200px;
      opacity: 0.5;
    }

    .hero-inner {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4rem;
      align-items: center;
    }

    .hero-content {
      max-width: 540px;
    }

    .hero-title {
      font-size: clamp(2.5rem, 5vw, 3.5rem);
      font-weight: 800;
      line-height: 1.1;
      margin-bottom: 1.5rem;
    }

    .hero-subtitle {
      font-size: 1.125rem;
      line-height: 1.7;
      color: var(--gray-200);
      margin-bottom: 2rem;
    }

    .hero-buttons {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .hero-image {
      position: relative;
    }

    .hero-image img {
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow-xl);
    }

    .hero-image-placeholder {
      background: linear-gradient(135deg, var(--gray-300) 0%, var(--gray-400) 100%);
      border-radius: var(--radius-xl);
      aspect-ratio: 4/3;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-600);
      font-size: 0.875rem;
    }

    /* Section Common */
    .section {
      padding: 5rem 0;
    }

    .section-header {
      text-align: center;
      max-width: 640px;
      margin: 0 auto 3rem;
    }

    .section-label {
      display: inline-block;
      font-size: 0.8125rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--brand-red);
      margin-bottom: 0.75rem;
    }

    .section-title {
      font-size: clamp(2rem, 4vw, 2.75rem);
      font-weight: 700;
      color: var(--gray-900);
      margin-bottom: 1rem;
    }

    .section-subtitle {
      font-size: 1.0625rem;
      color: var(--gray-600);
    }

    /* Mission */
    .mission {
      background: var(--gray-50);
    }

    .mission-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4rem;
      align-items: center;
    }

    .mission-statement {
      font-size: 1.375rem;
      font-weight: 600;
      color: var(--brand-navy);
      line-height: 1.5;
      margin-bottom: 1.5rem;
    }

    .mission-text {
      color: var(--gray-600);
      line-height: 1.8;
    }

    .mission-values {
      display: flex;
      gap: 1rem;
      margin-top: 1.5rem;
    }

    .value-badge {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.5rem 1rem;
      background: var(--white);
      border-radius: var(--radius-lg);
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--gray-700);
      box-shadow: var(--shadow-sm);
    }

    .value-badge svg {
      width: 16px;
      height: 16px;
      color: var(--brand-red);
    }

    /* Impact Stats */
    .impact-stats {
      background: var(--brand-red);
      color: var(--white);
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 2rem;
    }

    .stat-item {
      text-align: center;
      padding: 2rem 1rem;
    }

    .stat-number {
      font-size: clamp(2.5rem, 5vw, 4rem);
      font-weight: 800;
      line-height: 1;
      margin-bottom: 0.5rem;
    }

    .stat-label {
      font-size: 1rem;
      opacity: 0.9;
    }

    /* Programs */
    .programs {
      background: var(--white);
    }

    .accordion {
      max-width: 800px;
      margin: 0 auto;
    }

    .accordion-item {
      border-bottom: 1px solid var(--gray-200);
    }

    .accordion-header {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 1.5rem 0;
      font-size: 1.125rem;
      font-weight: 600;
      color: var(--gray-800);
      text-align: left;
      transition: color var(--transition-fast);
    }

    .accordion-header:hover {
      color: var(--brand-red);
    }

    .accordion-icon {
      width: 24px;
      height: 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: transform var(--transition-base);
    }

    .accordion-item.active .accordion-icon {
      transform: rotate(180deg);
    }

    .accordion-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height var(--transition-slow);
    }

    .accordion-item.active .accordion-content {
      max-height: 500px;
    }

    .accordion-body {
      padding: 0 0 1.5rem;
      color: var(--gray-600);
      line-height: 1.7;
    }

    /* Get Involved */
    .get-involved {
      background: var(--gray-50);
    }

    .involve-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 2rem;
    }

    .involve-card {
      background: var(--white);
      padding: 2rem;
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-md);
      transition: all var(--transition-base);
    }

    .involve-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-xl);
    }

    .involve-icon {
      width: 56px;
      height: 56px;
      background: var(--brand-red);
      border-radius: var(--radius-lg);
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 1.5rem;
    }

    .involve-icon svg {
      width: 28px;
      height: 28px;
      color: var(--white);
    }

    .involve-card h3 {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--gray-900);
      margin-bottom: 0.75rem;
    }

    .involve-card p {
      color: var(--gray-600);
      margin-bottom: 1.5rem;
      line-height: 1.6;
    }

    /* News */
    .news {
      background: var(--white);
    }

    .carousel {
      position: relative;
    }

    .carousel-track {
      overflow: hidden;
    }

    .carousel-slides {
      display: flex;
      transition: transform var(--transition-slow);
    }

    .carousel-slide {
      flex: 0 0 100%;
      padding: 0 0.5rem;
    }

    .news-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.5rem;
    }

    .news-card {
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: all var(--transition-base);
    }

    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .news-image {
      aspect-ratio: 16/10;
      background: linear-gradient(135deg, var(--gray-300) 0%, var(--gray-400) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-600);
      font-size: 0.75rem;
    }

    .news-content {
      padding: 1.25rem;
    }

    .news-tag {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--brand-red);
      margin-bottom: 0.5rem;
    }

    .news-title {
      font-size: 1rem;
      font-weight: 600;
      color: var(--gray-800);
      margin-bottom: 0.5rem;
      line-height: 1.4;
    }

    .news-excerpt {
      font-size: 0.875rem;
      color: var(--gray-600);
      line-height: 1.5;
    }

    .carousel-nav {
      display: flex;
      justify-content: center;
      gap: 1rem;
      margin-top: 2rem;
    }

    .carousel-btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--white);
      border: 2px solid var(--gray-300);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition-fast);
    }

    .carousel-btn:hover {
      background: var(--brand-navy);
      border-color: var(--brand-navy);
      color: var(--white);
    }

    .carousel-btn svg {
      width: 20px;
      height: 20px;
    }

    .carousel-dots {
      display: flex;
      justify-content: center;
      gap: 0.5rem;
      margin-top: 1.5rem;
    }

    .carousel-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--gray-300);
      transition: all var(--transition-fast);
    }

    .carousel-dot.active {
      background: var(--brand-red);
      width: 24px;
      border-radius: 4px;
    }

    /* Donate CTA */
    .donate-cta {
      background: linear-gradient(135deg, var(--brand-navy) 0%, var(--brand-navy-light) 100%);
      color: var(--white);
    }

    .donate-cta-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4rem;
      align-items: center;
    }

    .donate-info h2 {
      font-size: clamp(2rem, 4vw, 2.75rem);
      font-weight: 700;
      margin-bottom: 1rem;
    }

    .donate-info p {
      font-size: 1.0625rem;
      opacity: 0.9;
      margin-bottom: 1.5rem;
      line-height: 1.7;
    }

    .impact-note {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.875rem;
      opacity: 0.8;
    }

    .impact-note svg {
      width: 16px;
      height: 16px;
    }

    .donate-form {
      background: var(--white);
      padding: 2rem;
      border-radius: var(--radius-xl);
      color: var(--gray-800);
    }

    .amount-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0.75rem;
      margin-bottom: 1rem;
    }

    .amount-option {
      padding: 0.875rem 0.5rem;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-md);
      font-weight: 600;
      font-size: 1rem;
      color: var(--gray-700);
      transition: all var(--transition-fast);
      text-align: center;
    }

    .amount-option:hover {
      border-color: var(--brand-red);
      color: var(--brand-red);
    }

    .amount-option.selected {
      background: var(--brand-red);
      border-color: var(--brand-red);
      color: var(--white);
    }

    .custom-amount {
      width: 100%;
      padding: 0.875rem 1rem;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-md);
      font-size: 1rem;
      margin-bottom: 1rem;
      transition: border-color var(--transition-fast);
    }

    .custom-amount:focus {
      outline: none;
      border-color: var(--brand-red);
    }

    .impact-list {
      margin: 1.5rem 0;
      padding: 1rem;
      background: var(--gray-50);
      border-radius: var(--radius-md);
    }

    .impact-item {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      padding: 0.5rem 0;
      font-size: 0.875rem;
      color: var(--gray-700);
    }

    .impact-item svg {
      width: 16px;
      height: 16px;
      color: var(--brand-red);
      flex-shrink: 0;
    }

    .donate-form .btn {
      width: 100%;
      padding: 1rem;
      font-size: 1rem;
    }

    /* Footer */
    .footer {
      background: var(--gray-900);
      color: var(--gray-300);
      padding: 4rem 0 2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 2fr repeat(3, 1fr);
      gap: 3rem;
      margin-bottom: 3rem;
    }

    .footer-brand p {
      margin-top: 1rem;
      font-size: 0.875rem;
      line-height: 1.7;
      color: var(--gray-400);
    }

    .footer-social {
      display: flex;
      gap: 1rem;
      margin-top: 1.5rem;
    }

    .footer-social a {
      width: 36px;
      height: 36px;
      background: var(--gray-800);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition-fast);
    }

    .footer-social a:hover {
      background: var(--brand-red);
    }

    .footer-col h4 {
      font-size: 0.875rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--white);
      margin-bottom: 1.25rem;
    }

    .footer-col ul {
      list-style: none;
    }

    .footer-col li {
      margin-bottom: 0.75rem;
    }

    .footer-col a {
      font-size: 0.875rem;
      transition: color var(--transition-fast);
    }

    .footer-col a:hover {
      color: var(--white);
    }

    .footer-bottom {
      padding-top: 2rem;
      border-top: 1px solid var(--gray-800);
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 1rem;
    }

    .footer-bottom p {
      font-size: 0.8125rem;
      color: var(--gray-500);
    }

    /* Modal */
    .modal-overlay {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: rgba(0, 0, 0, 0.6);
      z-index: 200;
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      visibility: hidden;
      transition: all var(--transition-base);
      padding: 1rem;
    }

    .modal-overlay.active {
      opacity: 1;
      visibility: visible;
    }

    .modal {
      background: var(--white);
      border-radius: var(--radius-xl);
      max-width: 480px;
      width: 100%;
      max-height: 90vh;
      overflow-y: auto;
      transform: scale(0.9) translateY(20px);
      transition: transform var(--transition-base);
    }

    .modal-overlay.active .modal {
      transform: scale(1) translateY(0);
    }

    .modal-header {
      padding: 1.5rem;
      border-bottom: 1px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .modal-header h3 {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--gray-900);
    }

    .modal-close {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-500);
      transition: all var(--transition-fast);
    }

    .modal-close:hover {
      background: var(--gray-100);
      color: var(--gray-700);
    }

    .modal-body {
      padding: 1.5rem;
    }

    .modal-body .donate-form {
      box-shadow: none;
      padding: 0;
      background: transparent;
    }

    /* Responsive */
    @media (max-width: 1024px) {
      .hero-inner {
        grid-template-columns: 1fr;
        text-align: center;
      }

      .hero-content {
        max-width: 600px;
        margin: 0 auto;
      }

      .hero-buttons {
        justify-content: center;
      }

      .hero-image {
        display: none;
      }

      .stats-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .mission-inner {
        grid-template-columns: 1fr;
        gap: 2rem;
      }

      .involve-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .donate-cta-inner {
        grid-template-columns: 1fr;
        gap: 2rem;
      }

      .news-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 768px) {
      .header-top {
        display: none;
      }

      .nav-desktop {
        display: none;
      }

      .hamburger {
        display: flex;
      }

      .mobile-nav {
        display: block;
      }

      .hero {
        padding: 6rem 0 4rem;
      }

      .section {
        padding: 3.5rem 0;
      }

      .stats-grid {
        grid-template-columns: 1fr 1fr;
        gap: 1rem;
      }

      .stat-item {
        padding: 1.5rem 0.5rem;
      }

      .involve-grid {
        grid-template-columns: 1fr;
      }

      .news-grid {
        grid-template-columns: 1fr;
      }

      .amount-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-grid {
        grid-template-columns: 1fr;
        gap: 2rem;
      }

      .footer-bottom {
        flex-direction: column;
        text-align: center;
      }
    }

    @media (max-width: 480px) {
      .hero-buttons {
        flex-direction: column;
      }

      .hero-buttons .btn {
        width: 100%;
      }

      .stats-grid {
        grid-template-columns: 1fr;
      }
    }

    /* Animations */
    @keyframes fadeInUp {
      from {
        opacity: 0;
        transform: translateY(20px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes countUp {
      from {
        opacity: 0;
      }
      to {
        opacity: 1;
      }
    }

    .animate-on-scroll {
      opacity: 0;
      transform: translateY(20px);
      transition: all 0.6s ease-out;
    }

    .animate-on-scroll.visible {
      opacity: 1;
      transform: translateY(0);
    }

    .stat-number {
      animation: countUp 0.5s ease-out forwards;
    }
  </style>
</head>
