  <script>
    // Mobile Navigation
    function toggleMobileNav() {
      const mobileNav = document.getElementById('mobileNav');
      const hamburger = document.querySelector('.hamburger');
      mobileNav.classList.toggle('active');
      hamburger.classList.toggle('active');
      document.body.style.overflow = mobileNav.classList.contains('active') ? 'hidden' : '';
    }

    // Donate Modal
    function openDonateModal() {
      document.getElementById('donateModal').classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function closeDonateModal(event) {
      if (event && event.target !== event.currentTarget) return;
      document.getElementById('donateModal').classList.remove('active');
      document.body.style.overflow = '';
    }

    // Amount Selection
    let selectedAmount = 50;

    function selectAmount(element, amount) {
      document.querySelectorAll('.amount-option').forEach(btn => btn.classList.remove('selected'));
      element.classList.add('selected');
      selectedAmount = amount;
    }

    function handleDonate() {
      const customAmount = document.querySelector('.modal .custom-amount, .donate-cta .custom-amount').value;
      const amount = customAmount || selectedAmount;
      alert(`Thank you for your generous donation of $${amount}! This will help us continue our humanitarian work.`);
    }

    // Accordion
    function toggleAccordion(header) {
      const item = header.parentElement;
      const wasActive = item.classList.contains('active');

      document.querySelectorAll('.accordion-item').forEach(i => i.classList.remove('active'));

      if (!wasActive) {
        item.classList.add('active');
      }
    }

    // Carousel
    let currentSlide = 0;

    function nextSlide() {
      currentSlide = (currentSlide + 1) % 1;
      updateCarousel();
    }

    function prevSlide() {
      currentSlide = (currentSlide - 1 + 1) % 1;
      updateCarousel();
    }

    function updateCarousel() {
      const slides = document.getElementById('carouselSlides');
      slides.style.transform = `translateX(-${currentSlide * 100}%)`;

      document.querySelectorAll('.carousel-dot').forEach((dot, i) => {
        dot.classList.toggle('active', i === currentSlide);
      });
    }

    // Scroll Animations
    const observerOptions = {
      threshold: 0.1,
      rootMargin: '0px 0px -50px 0px'
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
        }
      });
    }, observerOptions);

    document.querySelectorAll('.animate-on-scroll').forEach(el => observer.observe(el));

    // Stat Counter Animation
    function animateStats() {
      const stats = document.querySelectorAll('.stat-number');
      stats.forEach(stat => {
        const target = parseInt(stat.dataset.target);
        const prefix = stat.dataset.prefix || '';
        const suffix = stat.dataset.suffix || '';
        let current = 0;
        const increment = target / 50;
        const timer = setInterval(() => {
          current += increment;
          if (current >= target) {
            current = target;
            clearInterval(timer);
          }
          if (target >= 1000000) {
            stat.textContent = prefix + Math.floor(current / 1000000) + 'M' + suffix;
          } else if (target >= 1000) {
            stat.textContent = prefix + Math.floor(current / 1000) + 'K' + suffix;
          } else {
            stat.textContent = prefix + Math.floor(current) + suffix;
          }
        }, 30);
      });
    }

    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          animateStats();
          statsObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.5 });

    const statsSection = document.querySelector('.impact-stats');
    if (statsSection) {
      statsObserver.observe(statsSection);
    }

    // Escape key closes modal
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        closeDonateModal();
      }
    });
  </script>
